practice_tasks.solution:
def set_age(age):
    if age < 0:
        raise ValueError('Age cannot be negative')
    return age

print(set_age(25))

code_walkthrough.code:
def process_payment(amount):
    if amount <= 0:
        raise ValueError("Amount must be positive")
    print("Processing...")

try:
    process_payment(-50)
except ValueError as e:
    print(f"Caught: {e}")

challenge.solution:
def check_config(cfg):
    if 'host' not in cfg:
        raise KeyError('Missing host')
    if not isinstance(cfg['port'], int):
        raise TypeError('Port must be int')
    if cfg['port'] < 1024:
        raise ValueError('Port must be >= 1024')
    return True

check_config({'host': 'localhost', 'port': 8080})
